<script setup>
import {useI18n} from 'vue-i18n'
import {themeNames,accentNames} from './themes.js'
const {t}=useI18n()
const model=defineModel({required:true})
</script>
<template><div class="profile-fields"><label>{{t('themes.title')}}<select v-model="model.theme"><option v-for="name in themeNames" :key="name" :value="name">{{t('themes.'+name)}}</option></select></label><label>{{t('themes.accent')}}<select v-model="model.accent"><option v-for="name in accentNames" :key="name" :value="name">{{t('themes.'+name)}}</option></select></label><label>{{t('themes.appearance')}}<select v-model="model.appearance"><option value="theme">{{t('themes.themeDefault')}}</option><option value="light">{{t('config.light')}}</option><option value="dark">{{t('config.dark')}}</option><option value="auto">{{t('themes.auto')}}</option></select></label><label>{{t('themes.text')}}<select v-model="model.text_size"><option value="standard">{{t('themes.standard')}}</option><option value="large">{{t('themes.large')}}</option></select></label><label>{{t('layout.focus')}}<select v-model="model.focus_window"><option value="primary">{{t('layout.primary')}}</option><option value="weekly">{{t('layout.weekly')}}</option></select></label><label>{{t('layout.density')}}<select v-model="model.density"><option value="comfortable">{{t('layout.comfortable')}}</option><option value="compact">{{t('layout.compact')}}</option></select></label><label class="check-field"><input type="checkbox" v-model="model.show_clock">{{t('layout.clock')}}</label><label class="check-field"><input type="checkbox" v-model="model.show_weather">{{t('layout.weather')}}</label><label>{{t('city.title')}}<select v-model="model.weather_location"><option :value="null">{{t('city.default')}}</option><option :value="1796236">上海 · 中国</option><option :value="4699066">Houston · Texas · US</option><option v-if="model.weather_location&&![1796236,4699066].includes(model.weather_location)" :value="model.weather_location">#{{model.weather_location}}</option></select></label></div></template>
<style scoped>.profile-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.profile-fields label{min-width:0}@media(max-width:600px){.profile-fields{grid-template-columns:1fr}}</style>
